    static T20_ROUNDS: [&[FpBLS12]; 3] = [&T20_ROUND, &T20_ROUND, &T20_ROUND];

    struct SupportedStateSize16;
    impl PoseidonParams<FpBLS12> for SupportedStateSize16 {
