        assert_eq!(&a - &b, expected_difference);
        assert_eq!(a - &mut b_mut, expected_difference);

        assert_eq!(a * &b, expected_product);
        assert_eq!(&a * &b, expected_product);
        assert_eq!(a * &mut b_mut, expected_product);

        assert_eq!(a / &b, expected_quotient);
        assert_eq!(&a / &b, expected_quotient);
