        let borrowed_sum: Field64 = [&a, &b].into_iter().sum();
        let owned_product: Field64 = [a, b].into_iter().product();
        let borrowed_product: Field64 = [&a, &b].into_iter().product();
        assert_eq!(owned_sum, expected_sum);
