index fb5268c..5693da4 100644
--- a/lib/crypto/src/arithmetic/uint.rs
+++ b/lib/crypto/src/arithmetic/uint.rs
@@ -1705,4 +1705,57 @@ mod test {
         assert_eq!(format!("{one_limb}"), "0000000000000ABC");
         assert_eq!(format!("{one_limb:?}"), "0000000000000ABC");
     }
+
+    #[test]
+    fn runtime_comparisons_and_assignments_cover_carry_paths() {
+        use std::hint::black_box;
+
+        let greater = black_box(Uint::<2>::new([0, 1]));
+        let lesser = black_box(Uint::<2>::new([u64::MAX, 0]));
+        assert!(greater.ge(&lesser));
+        assert!(greater.gt(&lesser));
+        assert!(!greater.le(&lesser));
+        assert!(!greater.lt(&lesser));
+
+        let lesser = black_box(Uint::<2>::new([u64::MAX, 0]));
+        let greater = black_box(Uint::<2>::new([0, 1]));
+        assert!(!lesser.ge(&greater));
+        assert!(!lesser.gt(&greater));
+        assert!(lesser.le(&greater));
+        assert!(lesser.lt(&greater));
+        assert_eq!(greater.cmp(&greater), core::cmp::Ordering::Equal);
+
+        let mut add = black_box(U256::new([u64::MAX, u64::MAX, 0, 0]));
+        assert!(!add.checked_add_assign(&U256::ONE));
+        assert_eq!(add, U256::new([0, 0, 1, 0]));
+        let mut add_overflow = black_box(U256::MAX);
+        assert!(add_overflow.checked_add_assign(&U256::ONE));
+        assert_eq!(add_overflow, U256::ZERO);
+
+        let mut subtract = black_box(U256::new([0, 1, 0, 0]));
+        assert!(!subtract.checked_sub_assign(&U256::ONE));
+        assert_eq!(subtract, U256::new([u64::MAX, 0, 0, 0]));
+        let mut subtract_underflow = black_box(U256::ZERO);
+        assert!(subtract_underflow.checked_sub_assign(&U256::ONE));
+        assert_eq!(subtract_underflow, U256::MAX);
+
+        let mut shifted = black_box(U256::new([0, 1, 0, 0]));
+        assert!(!shifted.checked_mul2_assign());
+        assert_eq!(shifted, U256::new([0, 2, 0, 0]));
+        let mut shift_overflow = black_box(U256::MAX);
+        assert!(shift_overflow.checked_mul2_assign());
+        assert_eq!(
+            shift_overflow,
+            U256::new([u64::MAX - 1, u64::MAX, u64::MAX, u64::MAX])
+        );
+
+        let lhs = black_box(U256::new([u64::MAX, u64::MAX, 1, 0]));
+        let rhs = black_box(U256::new([3, 2, 0, 0]));
+        let (low, high) = lhs.widening_mul(&rhs);
+        let expected: AlloyU512 = AlloyU256::from_limbs(lhs.into_limbs())
+            .widening_mul(AlloyU256::from_limbs(rhs.into_limbs()));
+        let limbs: [u64; 8] = expected.into_limbs();
+        assert_eq!(low.into_limbs(), limbs[..4]);
+        assert_eq!(high.into_limbs(), limbs[4..]);
+    }
 }
diff --git a/lib/crypto/src/field/fp.rs b/lib/crypto/src/field/fp.rs
index d8932ee..1444bcc 100644
--- a/lib/crypto/src/field/fp.rs
+++ b/lib/crypto/src/field/fp.rs
@@ -1384,4 +1384,29 @@ mod tests {
         },))
         .is_err());
     }
+
+    #[test]
+    fn runtime_montgomery_and_negation_paths_match_field_arithmetic() {
+        use std::hint::black_box;
+
+        // Calling the const helper through a function pointer exercises the
+        // runtime implementation as well as the associated-constant use.
+        let inverse_fn: fn() -> u64 = black_box(inv::<Fp64Param, LIMBS_64>);
+        let inverse = inverse_fn();
+        assert_eq!(
+            Fp64Param::MODULUS.as_limbs()[0].wrapping_mul(inverse),
+            u64::MAX,
+        );
+
+        let nonzero = black_box(Field64::from(7u64));
+        assert_eq!(nonzero.neg(), Field64::from(999_996u64));
+        let zero = black_box(Field64::zero());
+        assert_eq!(zero.neg(), Field64::zero());
+
+        // A two-limb field executes both sides of the inner-limb selection in
+        // Montgomery reduction and checks the result against simple integers.
+        let lhs = black_box(Field128::from(123u64));
+        let rhs = black_box(Field128::from(456u64));
+        assert_eq!(lhs.mul(&rhs), Field128::from(56_088u64));
+    }
 }

